/**
 * Headlines — three per ticker, 42 in total.
 *
 * Deliberately boring: analyst notes, contract awards, delivery numbers,
 * partnerships, index changes. These are real, named companies, so there are no
 * invented scandals, lawsuits, investigations, accidents or personnel stories.
 * Nothing here implies material non-public information.
 *
 * Timestamps are derived from ANCHOR_DATE, never from the system clock. Every
 * ticker gets at least one item inside the anchor session, because delta.js and
 * breakouts.js both count anchor-session news and would otherwise read zero
 * across the board.
 */

import { ANCHOR_DATE, SYMBOLS } from "./companies.js"

const ANCHOR_UTC_OFFSET_HOURS = -4
const DAY_MS = 86400000
const [ANCHOR_Y, ANCHOR_M, ANCHOR_D] = ANCHOR_DATE.split("-").map(Number)

/**
 * UNIX seconds for a given ET wall-clock time, `sessionsBack` weekdays before
 * the anchor. Weekday-only, matching the candle generator — exchange holidays
 * are not modelled anywhere in this prototype.
 */
function at(sessionsBack, hourET, minuteET) {
  let cursor = Date.UTC(ANCHOR_Y, ANCHOR_M - 1, ANCHOR_D, 12, 0, 0)
  let remaining = sessionsBack
  while (remaining > 0) {
    cursor -= DAY_MS
    const weekday = new Date(cursor).getUTCDay()
    if (weekday !== 0 && weekday !== 6) remaining -= 1
  }
  const day = new Date(cursor)
  const utcMinutes = hourET * 60 + minuteET - ANCHOR_UTC_OFFSET_HOURS * 60
  return Math.floor(
    Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), 0, utcMinutes, 0) / 1000
  )
}

