function buildItems(symbol, entries) {
  return entries.map((entry, index) => {
    const [headline, source, summary, sessionsBack, hourET, minuteET] = entry
    return {
      id: `${symbol.toLowerCase()}-${index + 1}`,
      symbol,
      headline,
      source,
      summary,
      timestamp: at(sessionsBack, hourET, minuteET),
    }
  })
}

export const NEWS = SYMBOLS.reduce((acc, symbol) => {
  acc[symbol] = buildItems(symbol, RAW[symbol] || [])
  return acc
}, {})

export function getNews(symbol) {
  if (!symbol) return []
  return NEWS[String(symbol).trim().toUpperCase()] || []
}

/** Newest first, with a stable id tie-break so the order never wobbles. */
export function getAllNews() {
  const all = []
  for (const symbol of SYMBOLS) all.push(...NEWS[symbol])
  return all.sort((a, b) => b.timestamp - a.timestamp || a.id.localeCompare(b.id))
}

export function getLatestNews(limit = 10) {
  return getAllNews().slice(0, limit)
}

/** Items whose timestamp falls in [from, to] — used by delta.js and breakouts.js. */
export function countNewsBetween(symbol, from, to) {
  const items = getNews(symbol)
  let count = 0
  for (const item of items) {
    if (item.timestamp >= from && item.timestamp <= to) count += 1
  }
  return count
}
