import React, { useEffect, useRef } from "react"

/**
 * The dashboard performance chart.
 *
 * GATSBY CONSTRAINT: lightweight-charts touches `window` at import time, and
 * Gatsby renders every page to HTML in Node at build time. A top-level
 * `import "lightweight-charts"` therefore breaks `gatsby build`.
 *
 * So the library is loaded with a dynamic import INSIDE useEffect, which only
 * ever runs in the browser. The server renders an empty sized container and the
 * chart mounts on hydration. Every chart in this codebase must follow this
 * pattern — there is no exception for sub-panels.
 *
 * Colours are read from the CSS custom properties at mount rather than
 * hard-coded, so the chart stays in step with tokens.css and no raw hex value
 * lives outside that file.
 */

/**
 * Reads a design token. Returns undefined when the token is missing, and every
 * call site drops undefined keys before handing options to the library — so no
 * colour value is ever duplicated in this file. tokens.css stays the only place
 * a colour is written down.
 */
function readToken(styles, name) {
  const value = styles.getPropertyValue(name)
  return value && value.trim() ? value.trim() : undefined
}

/** Strips undefined entries so the library falls back to its own defaults. */
function defined(object) {
  const out = {}
  for (const key of Object.keys(object)) {
    if (object[key] !== undefined) out[key] = object[key]
  }
  return out
}

export default function MarketChart({
  data = [],
  height = 340,
  intraday = false,
  type = "area",
}) {
  const containerRef = useRef(null)

  useEffect(() => {
    let chart = null
    let observer = null
    let cancelled = false

    async function mount() {
      const container = containerRef.current
      if (!container) return

      const { createChart, LineStyle } = await import("lightweight-charts")
      // The component may have unmounted while the chunk was loading.
      if (cancelled || !containerRef.current) return

      const styles = window.getComputedStyle(document.documentElement)
      const line = readToken(styles, "--chart-line")
      const grid = readToken(styles, "--chart-grid")
      const axis = readToken(styles, "--chart-axis")
      const crosshair = readToken(styles, "--chart-crosshair")
      const surface = readToken(styles, "--surface")

      chart = createChart(container, {
        width: container.clientWidth,
        height,
        layout: {
          background: defined({ color: surface }),
          ...defined({ textColor: axis, fontFamily: readToken(styles, "--font-ui") }),
          fontSize: 11,
        },
        grid: {
          vertLines: { ...defined({ color: grid }), style: LineStyle.Solid },
          horzLines: { ...defined({ color: grid }), style: LineStyle.Solid },
        },
        rightPriceScale: {
          borderVisible: false,
          scaleMargins: { top: 0.12, bottom: 0.08 },
        },
        timeScale: {
          borderVisible: false,
          timeVisible: intraday,
          secondsVisible: false,
          fixLeftEdge: true,
          fixRightEdge: true,
        },
        crosshair: {
          vertLine: { ...defined({ color: crosshair, labelBackgroundColor: line }), width: 1, style: LineStyle.Dashed },
          horzLine: { ...defined({ color: crosshair, labelBackgroundColor: line }), width: 1, style: LineStyle.Dashed },
        },
        handleScale: false,
        handleScroll: false,
      })

      const series =
        type === "line"
          ? chart.addLineSeries({
              ...defined({ color: line }),
              lineWidth: 2,
              priceLineVisible: false,
            })
          : chart.addAreaSeries({
              ...defined({
                lineColor: line,
                topColor: readToken(styles, "--chart-area-top"),
                bottomColor: readToken(styles, "--chart-area-bottom"),
              }),
              lineWidth: 2,
              priceLineVisible: false,
            })

      series.setData(data)
      chart.timeScale().fitContent()

      // Keep the canvas in step with its container.
      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(entries => {
          if (!chart || !entries.length) return
          chart.applyOptions({ width: Math.floor(entries[0].contentRect.width) })
          chart.timeScale().fitContent()
        })
        observer.observe(container)
      }
    }

    mount()

    return () => {
      cancelled = true
      if (observer) observer.disconnect()
      if (chart) chart.remove()
    }
  }, [data, height, intraday, type])

  return (
    <div className="chart">
      <div className="chart__canvas" ref={containerRef} style={{ height: height + "px" }} />
    </div>
  )
}
