import React from "react"

import TickerMark from "../ui/TickerMark"
import Delta from "../ui/Delta"
import BreakoutChart from "../charts/BreakoutChart"

/**
 * One breakout candidate, at working density.
 *
 * The card has to make the event legible in about a second, so the chart carries
 * the actual breakout level and the bar where price crossed it — not a
 * decorative sparkline. Every figure below is read off the same generated series
 * the chart draws.
 */

const DASH = "—"

const usd = (n, d = 2) => (n === null || !Number.isFinite(n) ? DASH : "$" + n.toFixed(d))

function compact(n) {
  if (n === null || !Number.isFinite(n)) return DASH
  const a = Math.abs(n)
  if (a >= 1e9) return (n / 1e9).toFixed(2) + "B"
  if (a >= 1e6) return (n / 1e6).toFixed(1) + "M"
  if (a >= 1e3) return (n / 1e3).toFixed(1) + "K"
  return String(Math.round(n))
}

/**
 * The dataset is anchored to a fixed session in Eastern time, so the offset is a
 * constant rather than a timezone lookup — the label reads the same on every
 * machine.
 */
const ET_OFFSET_HOURS = -4

function sessionTime(timestamp) {
  if (!Number.isFinite(timestamp)) return null
  const d = new Date((timestamp + ET_OFFSET_HOURS * 3600) * 1000)
  const hh = String(d.getUTCHours()).padStart(2, "0")
  const mm = String(d.getUTCMinutes()).padStart(2, "0")
  return `${hh}:${mm} ET`
}

function Metric({ label, children }) {
  return (
    <div className="bo__metric">
      <span className="bo__metric-label">{label}</span>
      <span className="bo__metric-value">{children}</span>
    </div>
  )
}

export default function BreakoutCard({ row }) {
  if (!row) return null

  const detected = sessionTime(row.detectedAt)
  const rvol = row.rvol === null || !Number.isFinite(row.rvol) ? DASH : row.rvol.toFixed(2) + "x"
  const passed = row.checklist ? row.checklist.filter(c => c.passed).length : 0
  const total = row.checklist ? row.checklist.length : 0

  return (
    <article className="bo">
      <header className="bo__head">
        <div className="bo__identity">
          <TickerMark symbol={row.symbol} size={26} />
          <div className="bo__identity-text">
            <span className="bo__symbol">{row.symbol}</span>
            <span className="bo__name">{row.name}</span>
          </div>
        </div>
        <span className="bo__type">{row.signal}</span>
      </header>

      <div className="bo__price-row">
        <span className="bo__price">{usd(row.price)}</span>
        <Delta value={row.changePct} percent digits={2} />
        <span className="bo__window">1D</span>
      </div>

      <BreakoutChart
        values={row.series}
        level={row.breakoutLevel}
        width={280}
        height={64}
        label={`${row.symbol} price against its ${row.breakoutLevel} breakout level`}
      />

      <div className="bo__metrics">
        <Metric label="Breakout level">{usd(row.breakoutLevel)}</Metric>
        <Metric label="Above level">
          <Delta value={row.distancePct} percent digits={2} showGlyph={false} />
        </Metric>
        <Metric label="RVOL">{rvol}</Metric>
        <Metric label="Volume">{compact(row.volume)}</Metric>
      </div>

      <footer className="bo__foot">
        <div className="bo__score">
          <span className="bo__score-value">{row.score}</span>
          <span className="bo__score-total">/100 momentum</span>
          <span className="bo__score-track" aria-hidden="true">
            <span className="bo__score-fill" style={{ width: row.score + "%" }} />
          </span>
        </div>
        <div className="bo__meta">
          <span className="bo__checks" title="Confirmation checks passed">
            {passed}/{total} checks
          </span>
          <span className="bo__detected">
            {detected ? detected : "Cleared pre-open"}
          </span>
        </div>
      </footer>
    </article>
  )
}
