import React from "react"

/**
 * A compact chart that shows an actual breakout, not a decorative squiggle.
 *
 * It answers one question — did price really cross this level, and where? — by
 * drawing four things:
 *   1. the session price path
 *   2. a dashed horizontal line at the breakout level
 *   3. a marker at the bar where price last crossed the level from below
 *   4. a filled dot at the current price
 *
 * The y-domain always includes the level, so the line is guaranteed to be inside
 * the frame; a chart that clipped its own reference level would be worse than no
 * chart. Pure SVG — no library, no measurement, renders identically on the
 * server and in the browser.
 */

const INSET = 3

/** Index of the last upward crossing of `level`, or null if it never crossed. */
function lastCrossing(values, level) {
  if (!Number.isFinite(level)) return null
  for (let i = values.length - 1; i > 0; i -= 1) {
    if (values[i - 1] <= level && values[i] > level) return i
  }
  return null
}

export default function BreakoutChart({
  values,
  level,
  width = 260,
  height = 68,
  className,
  label,
}) {
  if (!Array.isArray(values) || values.length < 2) return null

  let min = Infinity
  let max = -Infinity
  for (const v of values) {
    if (!Number.isFinite(v)) continue
    if (v < min) min = v
    if (v > max) max = v
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) return null

  // The level must be inside the frame or the whole point is lost.
  if (Number.isFinite(level)) {
    if (level < min) min = level
    if (level > max) max = level
  }

  // A little headroom so the level line and the price dot never touch the edge.
  const pad = (max - min) * 0.12 || Math.abs(max) * 0.01 || 1
  min -= pad
  max += pad

  const range = max - min
  const usable = height - INSET * 2
  const y = v => (range === 0 ? height / 2 : INSET + (1 - (v - min) / range) * usable)
  const stepX = width / (values.length - 1)
  const x = i => i * stepX

  const points = values.map((v, i) => `${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(" ")
  const levelY = Number.isFinite(level) ? y(level) : null
  const crossIdx = lastCrossing(values, level)

  const lastIdx = values.length - 1
  const lastValue = values[lastIdx]
  const cleared = Number.isFinite(level) && lastValue > level
  const tone = cleared ? "up" : "down"

  return (
    <svg
      className={["breakout-chart", className].filter(Boolean).join(" ")}
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      preserveAspectRatio="none"
      role="img"
      aria-label={
        label ||
        (Number.isFinite(level)
          ? `Price ${cleared ? "above" : "below"} the breakout level`
          : "Price path")
      }
      focusable="false"
    >
      {/* The region price has cleared, shaded so "above the level" reads instantly. */}
      {levelY !== null && (
        <rect
          className="breakout-chart__cleared"
          x="0"
          y="0"
          width={width}
          height={levelY.toFixed(2)}
        />
      )}

      {levelY !== null && (
        <line
          className="breakout-chart__level"
          x1="0"
          x2={width}
          y1={levelY.toFixed(2)}
          y2={levelY.toFixed(2)}
          vectorEffect="non-scaling-stroke"
        />
      )}

      <polyline
        className={"breakout-chart__line breakout-chart__line--" + tone}
        points={points}
        vectorEffect="non-scaling-stroke"
      />

      {/* Where price actually crossed. */}
      {crossIdx !== null && (
        <circle
          className="breakout-chart__cross"
          cx={x(crossIdx).toFixed(2)}
          cy={y(values[crossIdx]).toFixed(2)}
          r="3"
          vectorEffect="non-scaling-stroke"
        />
      )}

      {/* Current price. */}
      <circle
        className={"breakout-chart__now breakout-chart__now--" + tone}
        cx={x(lastIdx).toFixed(2)}
        cy={y(lastValue).toFixed(2)}
        r="2.5"
        vectorEffect="non-scaling-stroke"
      />
    </svg>
  )
}
